"""End one session and remove only files generated by this program."""
import re
import shutil

OUTPUT_FILES = ('resume.txt', 'jobs.json', 'jobs_nodes.json', 'result.json',
                'prepared.json', 'pending_match.json', 'last_error.txt',
                'conversations.sqlite', 'conversations.sqlite-wal',
                'conversations.sqlite-shm', 'conversations.sqlite-journal')


def is_goodbye(message):
    """Recognize short farewell messages while leaving ordinary job questions alone."""
    words = re.sub(r'[^\w]+', ' ', message.casefold()).strip()
    return words in {'bye', 'bye bye', 'goodbye', 'good bye', 'see you', 'see you later',
                     'that s all', 'that s all thanks', 'thats all', 'thats all thanks',
                     'that is all', 'that is all thanks', 'thanks bye', 'thank you bye',
                     'thank you goodbye', 'all done thanks', 'done thanks', 'exit', 'quit',
                     '再见', '拜拜', '结束', '谢谢就这些'}


def bye_tool(ctx):
    """Clear runtime outputs and tell the graph to end this session."""
    cleanup_generated(ctx)
    return {'status': 'ok', 'answer': 'Goodbye. This session is closed and its generated files are cleared.',
            'end_session': True}


def cleanup_generated(ctx, preserve_diagnostic=False):
    """Remove runtime outputs, optionally keeping a startup error for troubleshooting."""
    for name in OUTPUT_FILES:
        if preserve_diagnostic and name == 'last_error.txt':
            continue
        (ctx.data / name).unlink(missing_ok=True)
    directory = ctx.data / 'vector_db'
    if directory.is_symlink():
        directory.unlink()
    elif directory.is_dir():
        shutil.rmtree(directory)
